<template>
  <div class="flex min-h-screen bg-[var(--sd-bg)]">
    <aside class="hidden w-[235px] shrink-0 border-r border-slate-200 bg-white md:block"><div class="h-[62px] border-b border-slate-100 px-5 py-5"><h1 class="text-sm font-bold text-slate-900">Settings</h1></div><nav class="h-[calc(100vh-62px)] overflow-y-auto px-3 py-4">
      <div v-for="group in groups" :key="group.label" class="mb-4"><button @click="group.open=!group.open" class="flex w-full items-center justify-between px-2 py-2 text-[11px] font-bold text-slate-700"><span>{{group.label}}</span><ChevronDown :class="['h-3.5 w-3.5 text-slate-400 transition',group.open?'':'-rotate-90']"/></button><div v-if="group.open" class="space-y-0.5"> <button v-for="item in group.items" :key="item" @click="active=item" :class="['flex w-full items-center gap-2.5 rounded-lg px-3 py-2 text-left text-[11px] transition',active===item?'bg-blue-600 font-semibold text-white shadow-sm':'text-slate-600 hover:bg-slate-50 hover:text-slate-900']"><component :is="iconFor(item)" class="h-3.5 w-3.5"/>{{item}}</button></div></div>
    </nav></aside>
    <main class="min-w-0 flex-1 p-5 md:p-7 xl:px-9"><div class="mb-4 md:hidden"><select v-model="active" class="h-10 w-full rounded-lg border border-slate-200 bg-white px-3 text-xs font-semibold"><optgroup v-for="group in groups" :key="group.label" :label="group.label"><option v-for="item in group.items" :key="item">{{item}}</option></optgroup></select></div><div class="mb-6 flex items-center justify-between"><div><div class="text-[10px] font-bold uppercase tracking-[.15em] text-blue-600">Workspace configuration</div><h2 class="mt-1 text-2xl font-bold tracking-tight text-slate-900">{{active}}</h2><p class="mt-1 text-xs text-slate-500">Manage {{active.toLowerCase()}} preferences for your company workspace.</p></div><span class="hidden rounded-full border border-emerald-200 bg-emerald-50 px-3 py-1.5 text-[10px] font-semibold text-emerald-700 sm:inline-flex">Changes are local demo data</span></div>
      <template v-if="active==='Inbox Appearance'"><section class="rounded-2xl border border-blue-100 bg-white p-5 md:p-6"><h3 class="text-sm font-bold">Chat background</h3><p class="mt-1 text-xs text-slate-500">Choose a subtle background for your inbox conversation area.</p><div class="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-4"><button v-for="pattern in patterns" :key="pattern" @click="selectedPattern=pattern" :class="['overflow-hidden rounded-xl border text-center transition',selectedPattern===pattern?'border-blue-500 ring-2 ring-blue-100':'border-slate-200 hover:border-slate-300']"><div :class="['grid h-20 place-items-center text-2xl text-slate-300',patternClass(pattern)]">{{pattern==='None'?'':pattern==='Dots'?'· · ·':pattern==='Lines'?'〰 〰':'✳'}}</div><div class="py-2 text-[11px] font-medium text-slate-600">{{pattern}} <span v-if="selectedPattern===pattern" class="text-blue-600">✓</span></div></button></div><div class="mt-5 rounded-xl bg-slate-50 p-4"><label class="flex items-center gap-3"><input v-model="channelBackground" type="checkbox" class="h-4 w-4 rounded border-slate-300 text-blue-600"/><span><b class="block text-xs">Channel-specific background</b><small class="text-[10px] text-slate-500">Use a different background for each connected WhatsApp number.</small></span></label></div></section><section class="mt-5 rounded-2xl border border-blue-100 bg-white p-5"><h3 class="text-sm font-bold">User avatars</h3><div class="mt-4 flex items-center justify-between rounded-xl bg-slate-50 p-4"><div class="flex items-center gap-3"><div class="flex -space-x-2"><span class="grid h-9 w-9 place-items-center rounded-full border-2 border-white bg-amber-100 text-xs">S</span><span class="grid h-9 w-9 place-items-center rounded-full border-2 border-white bg-emerald-100 text-xs">N</span><span class="grid h-9 w-9 place-items-center rounded-full border-2 border-white bg-violet-100 text-xs">M</span></div><div><b class="block text-xs">Colorful avatars</b><small class="text-[10px] text-slate-500">Use generated colors for contact initials.</small></div></div><input v-model="colorfulAvatars" type="checkbox" class="h-5 w-5 accent-blue-600"/></div></section></template>
      <template v-else-if="active==='Audit Logs'"><section class="overflow-hidden rounded-2xl border border-slate-200 bg-white"><div class="flex flex-wrap items-center justify-between gap-3 border-b border-slate-100 p-4"><div><h3 class="text-sm font-bold">Activity history</h3><p class="mt-1 text-[10px] text-slate-500">A read-only record of important workspace changes.</p></div><input v-model="auditSearch" placeholder="Search activity..." class="h-9 rounded-lg border border-slate-200 px-3 text-xs outline-none focus:border-blue-400"/></div><div class="overflow-x-auto"><table class="w-full min-w-[600px] text-left"><thead class="bg-slate-50 text-[10px] uppercase text-slate-500"><tr><th class="px-4 py-3">User</th><th class="px-4 py-3">Action</th><th class="px-4 py-3">Description</th><th class="px-4 py-3">Date & time</th></tr></thead><tbody><tr v-for="log in filteredLogs" :key="log.id" class="border-t border-slate-100 text-xs"><td class="px-4 py-3 font-semibold">{{log.user}}</td><td class="px-4 py-3"><span class="rounded-full bg-blue-50 px-2 py-1 text-[10px] font-semibold text-blue-700">{{log.action}}</span></td><td class="px-4 py-3 text-slate-600">{{log.description}}</td><td class="px-4 py-3 text-slate-500">{{log.date}}</td></tr></tbody></table></div></section></template>
      <template v-else><section class="rounded-2xl border border-blue-100 bg-white p-5 md:p-6"><div class="mb-5 flex items-start justify-between"><div><h3 class="text-sm font-bold">{{active}} configuration</h3><p class="mt-1 text-xs text-slate-500">Configure how {{active.toLowerCase()}} works in your workspace.</p></div><span class="rounded-lg bg-slate-100 px-2.5 py-1 text-[10px] font-semibold text-slate-500">General</span></div><div class="grid gap-4 md:grid-cols-2"><template v-for="field in fieldsFor(active)" :key="field.label"><label v-if="field.type==='text'" class="block text-[11px] font-semibold text-slate-600">{{field.label}}<input v-model="values[field.label]" :placeholder="field.placeholder||`Enter ${field.label.toLowerCase()}`" class="mt-1.5 h-10 w-full rounded-lg border border-slate-200 bg-white px-3 text-xs font-normal outline-none focus:border-blue-400"/></label><label v-else-if="field.type==='select'" class="block text-[11px] font-semibold text-slate-600">{{field.label}}<select v-model="values[field.label]" class="mt-1.5 h-10 w-full rounded-lg border border-slate-200 bg-white px-3 text-xs font-normal outline-none focus:border-blue-400"><option v-for="option in field.options" :key="option">{{option}}</option></select></label><label v-else-if="field.type==='textarea'" class="block text-[11px] font-semibold text-slate-600 md:col-span-2">{{field.label}}<textarea v-model="values[field.label]" rows="3" class="mt-1.5 w-full rounded-lg border border-slate-200 bg-white p-3 text-xs font-normal outline-none focus:border-blue-400" :placeholder="field.placeholder||'Write a message...'"/></label><div v-else class="flex items-center justify-between rounded-xl border border-slate-100 bg-slate-50 p-3"><div><b class="block text-xs text-slate-700">{{field.label}}</b><small class="text-[10px] text-slate-500">{{field.help||'Enable or disable this preference.'}}</small></div><input v-model="values[field.label]" type="checkbox" class="h-5 w-5 accent-blue-600"/></div></template></div><div class="mt-6 flex justify-end gap-2 border-t border-slate-100 pt-4"><button @click="resetSettings" class="rounded-lg border border-slate-200 px-4 py-2 text-xs font-semibold text-slate-600">Reset</button><button @click="saveSettings" class="rounded-lg bg-blue-600 px-5 py-2 text-xs font-semibold text-white hover:bg-blue-700">Save changes</button></div></section></template>
      <div v-if="toast" class="fixed bottom-5 right-5 rounded-xl bg-slate-900 px-4 py-3 text-xs font-medium text-white shadow-xl">{{toast}}</div>
    </main>
  </div>
</template>
<script setup lang="ts">
import {computed,reactive,ref,onMounted} from 'vue'
import {ChevronDown,UserRound,Building2,Palette,Bell,Image,Users,Clock,MessageSquare,Shield,Tag,CalendarDays,FileClock,Globe,KeyRound,History,SlidersHorizontal} from '@lucide/vue'
definePageMeta({layout:'dashboard'});useHead({title:'Settings — SumashDesk'})
const groups=reactive([{label:'General Settings',open:true,items:['Profile','Workspace','Appearance','Notifications']},{label:'Inbox Settings',open:true,items:['Inbox Appearance','Assignment Policy','Conversation Settings','SLA Settings','Tags Management']},{label:'WhatsApp Settings',open:true,items:['WhatsApp Numbers','Message Settings','Template Preferences']},{label:'Business Settings',open:true,items:['Business Hours','Away Messages']},{label:'Team & Security',open:true,items:['Roles & Permissions','Security','Audit Logs']}])
const active=ref('Profile'),selectedPattern=ref('Streamline'),channelBackground=ref(true),colorfulAvatars=ref(true),auditSearch=ref(''),toast=ref('')
const patterns=['None','Marble','Waves','Dots','Business','Grid','Soft waves','Streamline']
const icons:Record<string,any>={Profile:UserRound,Workspace:Building2,Appearance:Palette,Notifications:Bell,'Inbox Appearance':Image,'Assignment Policy':Users,'Conversation Settings':MessageSquare,'SLA Settings':Clock,'Tags Management':Tag,'WhatsApp Numbers':MessageSquare,'Message Settings':SlidersHorizontal,'Template Preferences':FileClock,'Business Hours':CalendarDays,'Away Messages':MessageSquare,'Roles & Permissions':Users,Security:Shield,'Audit Logs':History}
const iconFor=(n:string)=>icons[n]||Globe
const values=reactive<Record<string,any>>({'Company name':'SumashDesk','Contact email':'hello@sumashdesk.com','Business phone':'+880 1700-000000','Timezone':'Asia/Dhaka','Date format':'DD MMM YYYY','Time format':'12-hour','Theme':'Light','Desktop notifications':true,'Sound notifications':true,'Assignment notifications':true,'Default assignment':'Manual assignment','Default conversation status':'Open','First response target':'15 minutes','Resolution target':'8 hours','Working days':'Saturday – Thursday','Opening time':'09:00','Closing time':'18:00','Enable business hours':true,'Enable away message':false,'Away message':'Thanks for contacting us. Our team is currently offline and will reply during business hours.','Session timeout':'30 minutes','Allow CSV export':true,'Enable collision warning':true,'Show typing indicator':true,'Default language':'English','Connected number':' +880 1700-000000'})
const auditLogs=[{id:1,user:'Sadikul Islam',action:'Assignment',description:'Assigned Sumon Kundu conversation to Nusrat Jahan',date:'Nov 04, 2026 · 12:05 PM'},{id:2,user:'Nusrat Jahan',action:'Priority',description:'Changed Shalvi Hasan priority to High',date:'Nov 04, 2026 · 11:42 AM'},{id:3,user:'Sadikul Islam',action:'Settings',description:'Updated business hours',date:'Nov 03, 2026 · 05:10 PM'},{id:4,user:'Mahmud Hasan',action:'Contact',description:'Updated customer contact details',date:'Nov 03, 2026 · 02:22 PM'},{id:5,user:'Sadikul Islam',action:'Team',description:'Invited a new team member',date:'Nov 02, 2026 · 10:15 AM'}]
const filteredLogs=computed(()=>auditLogs.filter(l=>[l.user,l.action,l.description].join(' ').toLowerCase().includes(auditSearch.value.toLowerCase())))
function fieldsFor(name:string){const text=(label:string,placeholder?:string)=>({label,type:'text',placeholder});const select=(label:string,options:string[])=>({label,type:'select',options});const toggle=(label:string,help?:string)=>({label,type:'toggle',help});const area=(label:string,placeholder?:string)=>({label,type:'textarea',placeholder});const map:Record<string,any[]>={Profile:[text('Company name'),text('Contact email'),text('Business phone'),text('Company address')],Workspace:[select('Timezone',['Asia/Dhaka','Asia/Kolkata','UTC']),select('Date format',['DD MMM YYYY','MM/DD/YYYY','YYYY-MM-DD']),select('Time format',['12-hour','24-hour']),select('Default language',['English','Bengali'])],Appearance:[select('Theme',['Light','Dark','System']),toggle('Compact layout'),toggle('Reduce motion')],Notifications:[toggle('Desktop notifications'),toggle('Sound notifications'),toggle('Assignment notifications'),toggle('Follow-up notifications')],'Assignment Policy':[select('Default assignment',['Manual assignment','Round robin','Least active agent']),toggle('Allow agent reassignment'),toggle('Show agent availability')],'Conversation Settings':[select('Default conversation status',['Open','Pending']),select('Default priority',['Normal','High','Low']),toggle('Reopen resolved conversations'),toggle('Enable collision warning')],'SLA Settings':[text('First response target','15 minutes'),text('Resolution target','8 hours'),select('Warning threshold',['50%','75%','90%']),toggle('Use business hours for SLA')],'Tags Management':[text('New tag name'),select('Default tag color',['Blue','Green','Amber','Red','Violet'])],'WhatsApp Numbers':[text('Connected number','+880 1700-000000'),text('Display name','SumashDesk Support'),text('Phone Number ID'),text('WABA ID'),select('Connection status',['Connected','Disconnected']),toggle('Use as default inbox number')],'Message Settings':[toggle('Show delivery receipts'),toggle('Enable message retry'),toggle('Show 24-hour window indicator')],'Template Preferences':[select('Default language',['English','Bengali']),toggle('Show approved templates first')],'Business Hours':[select('Working days',['Saturday – Thursday','Sunday – Thursday','Every day']),text('Opening time','09:00'),text('Closing time','18:00'),select('Timezone',['Asia/Dhaka','Asia/Kolkata','UTC']),toggle('Enable business hours')],'Away Messages':[toggle('Enable away message'),area('Away message','Write your out-of-office message...'),select('Send when',['Outside business hours','Always when offline'])],'Roles & Permissions':[toggle('Agents can edit contact details'),toggle('Agents can export contacts'),toggle('Managers can view all reports')],Security:[select('Session timeout',['15 minutes','30 minutes','1 hour','8 hours']),toggle('Allow CSV export'),toggle('Require confirmation for destructive actions') ]};return map[name]||[toggle('Enable this feature')]}
function notify(s:string){toast.value=s;setTimeout(()=>toast.value='',2200)}function saveSettings(){if(import.meta.client){localStorage.setItem('sumashdesk-settings-demo',JSON.stringify({values,selectedPattern:selectedPattern.value,channelBackground:channelBackground.value,colorfulAvatars:colorfulAvatars.value}))}notify(`${active.value} saved successfully`)}function resetSettings(){if(import.meta.client){localStorage.removeItem('sumashdesk-settings-demo')}notify('Demo settings cleared. Reload to restore defaults')}onMounted(()=>{const saved=localStorage.getItem('sumashdesk-settings-demo');if(saved){try{const parsed=JSON.parse(saved);Object.assign(values,parsed.values||{});selectedPattern.value=parsed.selectedPattern||selectedPattern.value;channelBackground.value=parsed.channelBackground??channelBackground.value;colorfulAvatars.value=parsed.colorfulAvatars??colorfulAvatars.value}catch{localStorage.removeItem('sumashdesk-settings-demo')}}})
function patternClass(p:string){return p==='Dots'?'bg-[radial-gradient(#cbd5e1_1px,transparent_1px)] [background-size:12px_12px]':p==='Grid'?'bg-[linear-gradient(45deg,transparent_46%,#e2e8f0_48%,#e2e8f0_52%,transparent_54%)] [background-size:18px_18px]':p==='Waves'||p==='Soft waves'?'bg-[repeating-linear-gradient(0deg,#fff,#fff_10px,#e2e8f0_11px,#fff_13px)]':'bg-slate-100'}
</script>
